import numpy as np, os

fwd = '/work/fwd'
print("fwd exists:", os.path.exists(fwd))

if os.path.exists(fwd):
    runs = sorted(os.listdir(fwd))
    print("Runs:", runs)
    for run in runs:
        p = f'{fwd}/{run}/run.npz'
        if os.path.exists(p):
            d = np.load(p, allow_pickle=True)
            print(f"\n{run}: {list(d.keys())}")
            # Show attention patterns
            for k in d.keys():
                if 'pattern' in k.lower():
                    print(f"  {k}[0]:\n{np.round(d[k][0], 2)}")
            if 'logits' in d:
                print(f"  preds: {np.argmax(d['logits'], axis=-1)}")
else:
